package com.gamelaunch.frontend.pocket.data

/**
 * Pre-fetched IGDB metadata for 93 Steam games.
 * Generated from IGDB API — seeded on first launch.
 * Re-run the Python batch script to update.
 */
object IgdbSeedData {
    data class Entry(
        val steamAppId: String, val gameTitle: String,
        val mainSec: Int, val plusSec: Int, val compSec: Int,
        val developer: String?, val publisher: String?, val summary: String?
    )

    val entries: List<Entry> = listOf(
        Entry("202170", "Sleeping Dogs™", 61200, 72771, 148800, "United Front Games", "Bandai Namco Entertainment", "Sleeping Dogs is a third-person open-world action-adventure game set in contemporary Hong Kong. Players control Wei Shen, an undercover police officer who infiltrates a Triad organization called the Sun On Yee. Gameplay emphasizes melee combat using martial arts moves, grapples, and environmental attacks over gunplay, alongside driving, parkour, and open-world exploration. The game features a trip"),
        Entry("8190", "Just Cause 2", 0, 0, 0, "Anco Software Ltd.", "Anco Software Ltd.", "Player Manager 2 sets you as an international-standard soccer player who's stepped into being a player-manager at a lower-division side. The challenge is to reach the Premier League and survive.  Most of the standard features of management games are present, including pre-match tactics (which are fairly customizable), a full transfer market including short-term loan deals, detailed player statisti"),
        Entry("1808500", "ARC Raiders", 0, 360000, 360000, "Embark Studios", "Embark Studios", "ARC Raiders is a multiplayer extraction adventure, set in a lethal future earth, ravaged by a mysterious mechanized threat known as ARC. Enlist as a Raider and scavenge the surface to thrive in a desolate world. But beware of the machines. Beware of Raiders preying on others.  ARC Raiders blends the tension from extraction shooters with atmospheric settings from the adventure genre. Lurking threat"),
        Entry("35720", "Trine 2", 25200, 36216, 85200, "Frozenbyte", "Atlus", "Three Heroes survive in countless dangers in a fairy-tale world, with physics-based jigsaw puzzles, beautiful scenery, and cooperative online mode."),
        Entry("400", "Portal", 6825, 14766, 27163, "Valve", "Valve", "Waking up in a seemingly empty laboratory, the player is made to complete various physics-based puzzle challenges through numerous test chambers in order to test out the new Aperture Science Handheld Portal Device, without an explanation as to how, why or by whom."),
        Entry("1649240", "Returnal™", 39600, 114000, 0, "Housemarque", "Sony Interactive Entertainment", "Returnal is a 2021 roguelike third-person shooter video game developed by Housemarque and published by Sony Interactive Entertainment.  It follows Selene Vassos, an astronaut who lands on the planet Atropos in search of the mysterious \"White Shadow\" signal and finds herself trapped in a time loop.  After crash-landing on a shape-shifting alien planet, Selene finds herself fighting tooth and nail f"),
        Entry("49520", "Borderlands 2", 109920, 239400, 524160, "Gearbox Software", "2K Games", "A new era of shoot and loot is about to begin. Play as one of four new vault hunters facing off against a massive new world of creatures, psychos and the evil mastermind, Handsome Jack. Make new friends, arm them with a bazillion weapons and fight alongside them in 4 player co-op on a relentless quest for revenge and redemption across the undiscovered and unpredictable living planet."),
        Entry("7670", "BioShock", 28800, 43200, 57600, "Radical Entertainment", "Sierra Entertainment", "Crash of the Titans is the sixth Crash Bandicoot series game. The gameplay has the player explore levels, picking up power-ups to use against enemies as well as for the first time, use fighting combos such as punches and kicks against enemies. When Crash defeats an enemy or destroys an object, a magical substance known as Mojo is released. If the player collects enough Mojo, he will earn either an"),
        Entry("1203620", "Enshrouded", 0, 720000, 0, "Keen Games", "Keen Games", "You are Flameborn, last ember of hope of a dying race. Awaken, survive the terror of a corrupting fog, and reclaim the lost beauty of your kingdom. Venture into a vast world, vanquish punishing bosses, build grand halls and forge your path in this co-op survival Action RPG for up to 16 players."),
        Entry("8930", "Sid Meier's Civilization V", 41400, 190800, 1839600, "Firaxis Games", "Aspyr Media", "Sid Meier's Civilization V is a turn-based strategy game in which players lead a civilization from the ancient era through the future. Players found cities, research technologies, build improvements, train military units, and engage in diplomacy with AI or human opponents. Victory can be achieved through domination, science, culture, diplomacy, or by having the highest score when time runs out. Th"),
        Entry("553850", "HELLDIVERS™ 2", 0, 0, 144000, "Arrowhead Game Studios", "Sony Interactive Entertainment", "Helldivers 2 is a cooperative third-person shooter in which squads of up to four players are deployed from orbit onto hostile planets to complete strategic missions. Players select loadouts of weapons, armor, and stratagems that allow them to call in orbital strikes, supply drops, vehicles, and turrets during combat. Friendly fire is always active, requiring coordination between teammates. The gam"),
        Entry("2054970", "Dragon's Dogma 2", 111600, 173700, 259200, "Capcom Development Division 1", "Capcom", "Dragon's Dogma is a single player, narrative driven action-RPG that challenges players to choose their own experience – from the appearance of their Arisen, their vocation, their party, how to approach different situations and more.  On your journey, you’ll be joined by Pawns, mysterious otherworldly beings, in an adventure so unique you will feel as if accompanied by other players while on your o"),
        Entry("107100", "Bastion", 21240, 32512, 53760, "Supergiant Games", "WB Games", "A hack-and-slash RPG featuring a reactive narrator, various unlockable weapons, weapon upgrades, practice mini-games and optional difficulty modifiers, set in an imaginary world in the aftermath of an uncertain apocalypse, in which the player embodies a teenager with a troubled past as he and the narrator work together to rebuild the world out of a persisting hub called the Bastion."),
        Entry("225080", "Brothers - A Tale of Two Sons", 9600, 11560, 19980, "Starbreeze Studios", "505 Games", "Brothers is presented from a third-person view overlooking the two brothers. The brothers are moved individually by two thumbsticks on the controller. The controller triggers also cause the respective brother to interact with the game world, such as talking to a non-player character or grabbing onto a ledge or object.  The older brother is the stronger of the two and can pull levers or boost his y"),
        Entry("241930", "Middle-earth™: Shadow of Mordor™", 0, 64440, 204214, "Monolith Productions", "WB Games", "Middle-earth: Shadow of Mordor is a open world third-person action role-playing video game developed by Monolith Productions and published by Warner Bros. Interactive Entertainment, which takes place in the world of J.R.R. Tolkien's Legendarium.  The game takes place in the 60-year gap between the events of Tolkien's The Hobbit and The Lord of The Rings. It is a story of revenge, slaughter, and my"),
        Entry("990080", "Hogwarts Legacy", 85200, 156407, 293200, "Avalanche Software", "Warner Bros. Games", "Hogwarts Legacy is an immersive, open-world action RPG set in the world first introduced in the Harry Potter books. Now you can take control of the action and be at the center of your own adventure in the wizarding world. Embark on a journey through familiar and new locations as you explore and discover fantastic beasts, customize your character and craft potions, master spell casting, upgrade tal"),
        Entry("2358720", "Black Myth: Wukong", 93600, 157680, 244800, "Game Science", "Game Science", "Black Myth: Wukong is an action role-playing game developed by Game Science, inspired by the classical Chinese novel Journey to the West. Players control the Destined One, a staff-wielding monkey protagonist, through mostly linear levels interspersed with expansive areas. The game features Soulslike elements, a flexible skill system, and boss encounters of varying intensity. It was the first insta"),
        Entry("1172470", "Apex Legends", 127200, 1053600, 3844800, "Respawn Entertainment", "Electronic Arts", "Conquer with character in Apex Legends, a free-to-play Hero shooter where legendary characters with powerful abilities team up to battle for fame & fortune on the fringes of the Frontier.  Master an ever-growing roster of diverse Legends, deep tactical squad play and bold new innovations that go beyond the Battle Royale experience—all within a rugged world where anything goes. Welcome to the next"),
        Entry("739630", "Phasmophobia", 0, 75600, 0, "Kinetic Games", "Kinetic Games", "Phasmophobia is a cooperative horror investigation game played from a first-person perspective, supporting one to four players. Players take on the role of ghost hunters who must identify the type of ghost haunting a designated location by gathering evidence using various paranormal investigation equipment. The game features speech recognition, allowing ghosts and certain equipment to respond to w"),
        Entry("22380", "Fallout: New Vegas", 75860, 189774, 341844, "Obsidian Entertainment", "Bandai Namco Entertainment", "In this first-person Western RPG, the player takes on the role of Courier 6, barely surviving after being robbed of their cargo, shot and put into a shallow grave by a New Vegas mob boss. The Courier sets out to track down their robbers and retrieve their cargo, and winds up getting tangled in the complex ideological and socioeconomic web of the many factions and settlements of post-nuclear Nevada"),
        Entry("1966720", "Lethal Company", 0, 0, 0, "Zeekerss", "Zeekerss", "A co-op horror roguelite about an abandoned industrial moon."),
        Entry("40800", "Super Meat Boy", 43200, 0, 183720, "Team Meat", "BlitWorks", "Super Meat Boy is a platform game in which players control Meat Boy, a small, dark red, cube-shaped character who must rescue his girlfriend Bandage Girl from the scientist Dr. Fetus. The game is divided into chapters containing over 300 levels, each requiring players to reach the end while avoiding saw blades, crumbling blocks, and other hazards. Players can jump, run on platforms, and slide down"),
        Entry("570940", "DARK SOULS™: REMASTERED", 72000, 165600, 195600, "QLOC", "Bandai Namco Entertainment", "Dark Souls Remastered is a remastered version of the original game Dark Souls. The updated version of the game features graphical enhancements, an expanded online mode, and the Artorias of the Abyss DLC."),
        Entry("209000", "Batman™: Arkham Origins", 54000, 76493, 152820, "WB Games Montréal", "WB Games", "Batman: Arkham Origins features an expanded Gotham City and introduces an original prequel storyline occurring several years before the events of Batman: Arkham Asylum and Batman: Arkham City."),
        Entry("1824220", "Chivalry 2", 0, 0, 0, "Torn Banner Studios", "Tripwire Interactive", "Chivalry 2 is a multiplayer first person slasher inspired by epic medieval movie battles. Players are thrust into the action of every iconic moment of the era - from clashing swords, to storms of flaming arrows, to sprawling castle sieges and more."),
        Entry("256290", "Child of Light", 0, 43200, 46800, "Ubisoft Montreal", "Ubisoft Entertainment", "The Black Queen has stolen the Sun, the Moon and the Stars. You play as Aurora, a young princess with a pure heart whose soul is brought to the kingdom of Lemuria. Embark on a quest to recapture the three sources of light, defeat the Black Queen and restore the kingdom of Lemuria."),
        Entry("214340", "Deponia", 0, 27600, 39600, "Daedalic Entertainment", "Daedalic Entertainment", "Deponia is a fast-paced comedy of errors and one of the most unusual love stories in gaming history. The twist-filled story takes its off-beat characters all over trash planet Deponia, a unique game world in the style of Douglas Adams, Terry Pratchett and Matt Groening. From Kuvaq, an improvised village built inside a giant trash heap, to the swimming black market and the dark corners of the eleva"),
        Entry("594650", "Hunt: Showdown 1896", 0, 0, 0, "Crytek Frankfurt", "Crytek", "Hunt the corrupted in backwaters lost to history. Fight back against a timeless evil that pits you against twisted monsters and other desperate Hunters – solo or in a group – in a high-stakes, tactical, PvPvE, first person shooter. There are no heroes here. Risk everything as Hunt consumes you."),
        Entry("374320", "DARK SOULS™ III", 96300, 185370, 381600, "FromSoftware", "Bandai Namco Entertainment", "Dark Souls III is an action role-playing game developed by FromSoftware and published by Bandai Namco Entertainment. Released in March 2016, it is the fourth entry in the Souls series and the final instalment in the Dark Souls trilogy. Set in the decaying kingdom of Lothric, players take on the role of the \"Ashen One,\" an undead warrior tasked with rekindling the First Flame to prevent the world f"),
        Entry("319630", "Life is Strange™", 34200, 56228, 75550, "DON'T NOD", "Feral Interactive", "Life Is Strange is a five part episodic game that sets out to revolutionize story based choice and consequence games by allowing the player to rewind time and affect the past, present and future."),
        Entry("241540", "State of Decay", 0, 0, 0, "Undead Labs", "Microsoft Studios", "The end is here. Life as you know it has gone to hell after the mother of all zombie outbreaks. Now you and the few scattered survivors must band together to survive and rebuild in a 3rd-person action game set in a dynamic open world. You choose where to make your stand, designing and fortifying your home base, performing daring raids for food and ammunition, and rescuing other playable survivors"),
        Entry("208650", "Batman™: Arkham Knight", 111600, 141894, 207600, "Rocksteady Studios", "Warner Bros. Interactive Entertainment", "Batman: Arkham Knight is an action-adventure game developed by Rocksteady Studios, released in 2015. It is the final installment in the Arkham series. Players control Batman as he faces Scarecrow, who unites Gotham's criminals to destroy the Dark Knight. The mysterious Arkham Knight, a new adversary, aids Scarecrow in his plan.  The game features open-world exploration, stealth, combat, and puzzle"),
        Entry("3768760", "007 First Light", 50400, 60685, 90000, "IO Interactive", "IO Interactive", "007 First Light is a thrilling espionage action-adventure game from IO Interactive. Players follow James Bond as a young, resourceful, and sometimes reckless recruit in MI6's training program and discover an origin story of the world's most famous spy."),
        Entry("3357650", "PRAGMATA", 35100, 52200, 86400, "Capcom", "Capcom", "Pragmata is a sci-fi action-adventure game set in the near future. The story follows Hugh and his android companion Diana as they navigate a Lunar research station. Gameplay incorporates action elements alongside mechanics involving interaction with systems within the environment."),
        Entry("50300", "Spec Ops: The Line", 22800, 22824, 36240, "Yager Development", "2K Games", "A third-person shooter in which three American soldiers led by Capt. Walker are sent to Dubai in order to recover whoever remains of an infantry unit, the 33rd Battalion, until they decide to take action against the militants situated in the city. As they progress, however, the logistical and ethical complexity of their objective deepens, and their perception of themselves, and their enemy, is put"),
        Entry("524220", "NieR:Automata™", 78410, 120009, 276726, "PlatinumGames", "Square Enix", "NieR: Automata tells the story of androids 2B, 9S and A2 and their battle to reclaim the machine-driven dystopia overrun by powerful machines."),
        Entry("214560", "Mark of the Ninja", 27000, 34305, 71400, "Klei Entertainment", "Microsoft Studios", "Mark of the Ninja is a side-scrolling action stealth video game developed by Klei Entertainment and published by Microsoft Studios. It was announced on February 28, 2012 and later released for the Xbox 360 via Xbox Live Arcade on September 7, 2012. A Microsoft Windows version was released on October 16, 2012. It follows the story of a nameless ninja in the present day, and features a themed confli"),
        Entry("3321460", "Crimson Desert Enhanced", 250800, 297000, 2655000, "Pearl Abyss", "Pearl Abyss", "Crimson Desert is an open-world action-adventure game set in the beautiful yet brutal continent of Pywel. Embark on a journey as the Greymane Kliff and restore what has been lost. Explore uncharted lands, fight against threats that stand in your way, and discover the wonders the world has in store."),
        Entry("204100", "Max Payne 3", 38400, 41622, 79200, "Rockstar New England", "Rockstar Games", "Max Payne 3 is a third-person shooter in which the player assumes the role of its titular character, Max Payne. A new feature to the series, introduced in Max Payne 3, is the cover system, which allows players to gain a tactical advantage, and avoid taking damage from enemies. To progress through the linear story, players take on enemies throughout levels. The game features interactive cutscenes w"),
        Entry("1600360", "The Cycle Playtest", 0, 0, 0, "Yager Development", "Yager Development", "The Cycle: Frontier is a PvP Extraction Shooter driven by suspense and danger. While you search for resources & loot on an alien planet, challenging fights against other players & encounters with vicious creatures constantly threaten your survival & your spoils."),
        Entry("2138710", "Sifu", 14400, 33120, 28800, "Sloclap", "Sloclap", "Sifu is a realistic third-person brawler with tight Kung Fu combat mechanics and cinematic martial arts action embarking you on a path for revenge."),
        Entry("1771300", "Kingdom Come: Deliverance II", 150000, 328800, 571500, "Warhorse Studios", "Deep Silver", "A thrilling story-driven action RPG, with a rich open world, set in 15th century Medieval Europe. Experience the ultimate medieval adventure - through the eyes of young Henry - as you embark on a journey of epic proportions."),
        Entry("1245620", "ELDEN RING", 160200, 429840, 625976, "FromSoftware", "Bandai Namco Entertainment", "Elden Ring is an action RPG developed by FromSoftware and published by Bandai Namco Entertainment, released in February 2022. Directed by Hidetaka Miyazaki, with world-building contributions from novelist George R. R. Martin, the game features an expansive open world called the Lands Between. Players assume the role of a customisable character known as the Tarnished, who must explore this world, b"),
        Entry("601150", "Devil May Cry 5", 18000, 31500, 0, "Capcom Development Division 1", "Capcom", "Devil May Cry 5 is a brand-new entry in the legendary over-the-top action series Devil May Cry. The game features three playable characters, each with a radically different stylish combat play style as they take on the city overrun with demons. Developed with Capcom’s in-house proprietary RE engine, the series continues to achieve new heights in fidelity with graphics that utilize photorealistic c"),
        Entry("391220", "Rise of the Tomb Raider", 41400, 78714, 175731, "Crystal Dynamics", "Microsoft Studios", "Rise of the Tomb Raider is a third-person action-adventure game in which players control Lara Croft as she searches for the legendary city of Kitezh and a promise of immortality. Combat involves firearms, stealth, and melee weapons, while semi-open hub areas offer challenge tombs with puzzles, side missions, and resource scavenging for crafting. Players earn experience and unlock skills across thr"),
        Entry("379720", "DOOM", 28800, 61748, 146400, "id Software", "Bethesda Softworks", "Developed by id software, the studio that pioneered the first-person shooter genre and created multiplayer Deathmatch, Doom returns as a brutally fun and challenging modern-day shooter experience. Relentless demons, impossibly destructive guns, and fast, fluid movement provide the foundation for intense, first-person combat – whether you’re obliterating demon hordes through the depths of Hell in t"),
        Entry("224760", "FEZ", 0, 26400, 45570, "Polytron Corporation", "Microsoft Studios", "Gomez is a 2D creature living in a 2D world. Or is he? When the existence of a mysterious 3rd dimension is revealed to him, Gomez is sent out on a journey that will take him to the very end of time and space. Use your ability to navigate 3D structures from 4 distinct classic 2D perspectives. Explore a serene and beautiful open-ended world full of secrets, puzzles and hidden treasures. Unearth the"),
        Entry("387290", "Ori and the Blind Forest: Definitive Edition", 32400, 47400, 60450, "Moon Studios", "Xbox Game Studios", "The forest of Nibel is dying. After a powerful storm sets a series of devastating events in motion, Ori must journey to find courage and confront a dark nemesis to save the forest of Nibel. “Ori and the Blind Forest” tells the tale of a young orphan destined for heroics, through a visually stunning Action-Platformer crafted by Moon Studios. Featuring hand-painted artwork, meticulously animated cha"),
        Entry("292030", "The Witcher 3: Wild Hunt - Complete Edition", 134552, 254778, 581483, "CD Projekt RED", "WB Games", "The Witcher 3: Wild Hunt is an open-world action role-playing game developed by CD Projekt Red.  Set in a dark fantasy world, the game follows Geralt of Rivia, a monster hunter searching for his adopted daughter, Ciri, while navigating political conflicts and supernatural threats. Gameplay features exploration, combat, character progression, and branching narratives shaped by player choices. Widel"),
        Entry("221910", "The Stanley Parable", 4200, 9675, 22073, "Galactic Cafe", "Galactic Cafe", "A first-person exploration game built around branching narrative choices and an omniscient narrator who reacts to the player's decisions. Players navigate an office environment, choosing whether to follow or defy the narrator's directions, with each choice leading to different story paths and endings. Originally released as a Half-Life 2 mod in 2011, it was remade as a standalone title in 2013 and"),
        Entry("35700", "Trine", 0, 0, 0, "Dimps", "Bandai Namco Games", "Saint Seiya: Sanctuary Battle immerses players in the most popular drama from Saint Seiya: the Sanctuary, as Seiya and his companions fight side by side to defeat the gold saints of the twelve palaces and protect Athena. As players complete quests and progress through the twelve levels, they can inflict tremendous damage on their foes with fast-paced Cosmo power-up attacks."),
        Entry("620", "Portal 2", 0, 0, 0, "tri-Ace", "Enix Corporation", "The first \"Star Ocean\" released outside of Japan. It was later re-released on the PSP under the name \"Star Ocean: Second Evolution\"."),
        Entry("238010", "Deus Ex: Human Revolution - Director's Cut", 36000, 85200, 108000, "Eidos Montréal", "Square Enix", "Deus Ex: Human Revolution - Director's Cut features approximately 8 hours of director's commentaries and a 45 minute “Making Of” video. It also features an improved visual engine and a complete overhaul of the boss battles.  Deus Ex: Human Revolution - Director's Cut is an expanded game for Deus Ex: Human Revolution which is an action role-playing game. It is the third game in the Deus Ex series,"),
        Entry("8850", "BioShock 2", 0, 0, 0, "Capcom", "Capcom", "Super Puzzle Fighter II X: For Matching Service is an online-enabled port of Capcom's puzzle fighting game with numerous bonus modes and features, exclusively for the Dreamcast."),
        Entry("20510", "S.T.A.L.K.E.R.: Clear Sky", 0, 0, 0, "Spike", "Eidos Interactive", "Bug Island is a island full of bugs and the perfect place for Michelle, who is majoring in insect physiology, to work on a report for school. Along come Mike, the typical confident college playboy and Ray, a freshman in college. Arriving on the island, Mike and Ray fight over Michelle who then runs off into the foggy distance and is nowhere to be found. Now Ray needs to find Michelle and get off t"),
        Entry("260230", "Valiant Hearts: The Great War™ / Soldats Inconnus : Mémoires de la Grande Guerre™", 0, 21540, 45600, "Ubisoft Montpellier", "Ubisoft Entertainment", "Valiant Hearts: The Great War is the story of 4 crossed destinies and a broken love in a world torn apart. Dive into a 2D animated comic book adventure, mixing exploration, action and puzzles. In Valiant Hearts, the lives of all these characters are inextricably drawn together over the course of the game. Friendship, love, sacrifice and tragedy befall each one as they help each other to retain the"),
        Entry("72850", "The Elder Scrolls V: Skyrim", 91440, 392583, 723927, "Bethesda Game Studios", "Bethesda Softworks", "Skyrim reimagines and revolutionizes the open-world fantasy epic, bringing to life a complete virtual world open for you to explore any way you choose. Play any type of character you can imagine, and do whatever you want; the legendary freedom of choice, storytelling, and adventure of The Elder Scrolls is realized like never before."),
        Entry("234140", "Mad Max", 72000, 215542, 250800, "Avalanche Studios", "Feral Interactive", "In Mad Max, the player takes on the role of titular character Mad Max; a dangerous melee fighter and can use his attacks to kill almost anyone. His weapon of choice is his shotgun. He is assisted by another man called Chumbucket. Chum mainly works with Max to build and upgrade the Magnum Opus vehicle.  Mad Max will feature a variety of weapons which Max can use to defeat enemies. Though the shotgu"),
        Entry("1145360", "Hades", 139240, 252900, 576000, "Supergiant Games", "Supergiant Games", "A rogue-lite hack and slash dungeon crawler in which Zagreus, son of Hades the Greek god of the dead, attempts to escape his home and his oppressive father by fighting the souls of the dead through the various layers of the ever-shifting underworld, while getting to know and forging relationships with its inhabitants."),
        Entry("233270", "Far Cry® 3 Blood Dragon", 16200, 26568, 38412, "Ubisoft Montreal", "Ubisoft Entertainment", "There’s only one force powerful enough to stop an army of rampaging killer cyborgs, mutated scientists, metal sharks and vicious Blood Dragons that shoot lasers from their eyes – that force is you. Your name is Sergeant Rex Power Colt, a Mark IV Cyber Commando. Lock and load as you and your seven favorite fully customizable killing implements tackle a bizarre open world island crawling with evil."),
        Entry("20900", "The Witcher: Enhanced Edition", 0, 0, 0, "Atari", "Atari", "Gran Trak 10 was a single-player racing arcade game released by Atari in 1974. The player raced against the clock, accumulating as many points as possible. Primitive diode-based ROM was used to store the sprites for the car, score and game timer, and the race track. The game's controls — steering wheel, four-position gear shifter, and accelerator and brake foot pedals — were also all firsts for ar"),
        Entry("231160", "The Swapper", 0, 0, 0, "Top Rated Design", "Top Rated Design", "Slyde is a classic sliding tile puzzle with 100 high quality images and 3 difficulty modes."),
        Entry("8870", "BioShock Infinite", 66180, 46800, 116280, "Looking Glass Studios", "Electronic Arts", "A first-person cyberpunk exploratory horror RPG and sequel to System Shock (1994) in which a soldier wakes up in the starship Von Braun in the aftermath of a disaster and finds himself in the midst of a conflict between SHODAN, the artificial intelligence antagonist of System Shock seeking mastery over humanity, and The Many, a flesh-based psychic hive mind led by the ship's corrupted AI."),
        Entry("221680", "Rocksmith® 2014 Edition - Remastered", 0, 0, 0, "Ubisoft San Francisco", "Ubisoft Entertainment", "The fastest way to learn guitar is now better than ever. With Rocksmith you can learn everything from single notes to chords and advanced techniques, all at your own pace. You'll learn fast because it adapts to your skill level as you play, whether you're a beginner or an experienced player.  This remastered version also includes six free bonus songs. \"Three Little Birds\" by Bob Marley & The Waile"),
        Entry("4000", "Garry's Mod", 33600, 120604800, 145800, "Facepunch Studios", "Valve", "Garry's Mod is a physics-based sandbox game built on Valve's Source engine. In its base mode, there are no objectives. Players can spawn non-player characters, ragdolls, and props, then manipulate them using a physics gun that can pick up, rotate, and freeze objects in place. A tool gun provides additional functionality such as welding objects together or adjusting facial expressions on ragdolls."),
        Entry("63380", "Sniper Elite V2", 22300, 29790, 52590, "Rebellion Developments", "505 Games", "Sniper Elite V2 is the eagerly-awaited sequel to the highly-acclaimed Sniper Elite, giving gamers the most authentic World War II sniping experience available. You are elite US sniper Karl Fairburne. Parachuted into Berlin amidst the Germans’ final stand, your mission is to prevent Nazi V2 rocket program technology from falling into the hands of the besieging Red Army. You must aid key scientists"),
        Entry("237110", "Mortal Kombat Komplete Edition", 216000, 189600, 270000, "NetherRealm Studios", "WB Games", "This Komplete Edition is a re-release of the original game. It includes the full game, alongside all previously released downloadable content. It also includes the Mortal Kombat: Songs Inspired by the Warriors album (including a bonus track) and the 1995 Mortal Kombat movie for download, via the PlayStation Store or Xbox Live Zune.  For the PS Vita and Windows this is the first release of the game"),
        Entry("237930", "Transistor", 15400, 26910, 54771, "Supergiant Games", "Supergiant Games", "Transistor is an action role-playing game presented from an isometric perspective. Players control Red, a singer in the city of Cloudbank, as she wields a greatsword-like weapon called the Transistor against robotic enemies known as the Process. Combat can be played in real-time or paused using a planning mode called Turn(), which allows queuing actions for execution in a burst. Powers called Func"),
        Entry("1903340", "Clair Obscur: Expedition 33", 106690, 147888, 274650, "Sandfall Interactive", "Kepler Interactive", "Lead the members of Expedition 33 on their quest to destroy the Paintress so that she can never paint death again. Explore a world of wonders inspired by Belle Époque France and battle unique enemies in this turn-based RPG with real-time mechanics."),
        Entry("200260", "Batman: Arkham City GOTY", 36180, 81105, 286440, "Rocksteady Studios", "Warner Bros. Entertainment Inc.", "Batman: Arkham City - Game of the Year Edition includes the following DLC:  Catwoman Pack Nightwing Bundle Pack Robin Bundle Pack Harley Quinn’s Revenge Challenge Map Pack Arkham City Skins Pack  Batman: Arkham City - Game of the Year Edition packages new gameplay content, seven maps, three playable characters, and 12 skins beyond the original retail release:  Maps: Wayne Manor, Main Hall, Freight"),
        Entry("212680", "FTL: Faster Than Light", 38550, 74010, 0, "Subset Games", "Subset Games", "FTL: Faster Than Light is a single-player strategy game with roguelike design. The player commands a spaceship from a top-down view, managing systems such as weapons, engines, shields, and life support while recruiting crew and upgrading the vessel. The ship travels across procedurally generated sectors, jumping between beacons that present random events, stores, and enemy encounters. Combat plays"),
        Entry("220200", "Kerbal Space Program", 0, 0, 0, "Squad", "Private Division", "In Kerbal Space Program, take charge of the space program for the alien race known as the Kerbals. You have access to an array of parts to assemble fully-functional spacecraft that flies (or doesn’t) based on realistic aerodynamic and orbital physics. Launch your Kerbal crew into orbit and beyond (while keeping them alive) to explore moons and planets in the Kerbol solar system, constructing bases"),
        Entry("588650", "Dead Cells", 17550, 79200, 360000, "Motion Twin", "Playdigious", "Dead Cells is a 2D side-scrolling action platformer combining roguelike and Metroidvania design. Players control the Prisoner, an immortal creature that possesses corpses and fights through procedurally generated levels filled with mutated enemies. Combat centers on melee weapons, bows, traps, and dodging, with enemy patterns that reward careful observation. Death is permanent for each run, stripp"),
        Entry("250900", "The Binding of Isaac: Rebirth", 19560, 118200, 1357200, "Edmund McMillen", "Nicalis, Inc.", "A top-down roguelike action-adventure game and remake of the 2011 original, rebuilt from its Flash engine to enable expanded content and features. Players control Isaac through procedurally generated dungeon floors, using tears as projectiles to defeat monsters while collecting items that modify abilities and appearance in potentially powerful combinations. Runs end in permadeath, and each playthr"),
        Entry("870780", "Control Ultimate Edition", 48600, 81180, 112080, "Remedy Entertainment", "505 Games", "Control is a third-person action-adventure game set in the Federal Bureau of Control, a secretive U.S. government agency that studies paranormal phenomena. Players control Jesse Faden, who arrives at the Bureau's headquarters, the Oldest House, to find it invaded by a hostile force called the Hiss. Gameplay combines supernatural abilities with a shape-shifting firearm, and the environment is react"),
        Entry("753640", "Outer Wilds", 43200, 68400, 0, "Mobius Digital", "Annapurna Interactive", "Outer Wilds is a critically-acclaimed and award-winning open world mystery about a solar system trapped in an endless time loop. The newest member of the space program in a small village on the planet Timber Hearth, the player navigates a space shuttle and travels across their solar system to get to the bottom of its mysteries by exploring the cosmos and gathering the knowledge hidden within each"),
        Entry("250320", "The Wolf Among Us", 28800, 36471, 46800, "Telltale Games", "Telltale Games", "The Wolf Among Us is a five-episode series from the creators of the 2012 Game of the Year: The Walking Dead. Based on Fables (DC Comics/Vertigo), an award-winning comic book series, it is an often violent, mature and hard-boiled thriller where the characters and creatures of myth, lore and legend are real and exist in our world. As Bigby Wolf - The Big Bad Wolf in human form - you will discover th"),
        Entry("952070", "RESIDENT EVIL RESISTANCE", 0, 0, 0, "NeoBards Entertainment", "Capcom", "Resident Evil: Resistance is a 1 vs. 4 asymmetric online survival horror experience set in the world of Resident Evil. Unleash your inner evil as a cunning Mastermind or join the fight as one of the resourceful Survivors desperately trying to escape every obstacle the Mastermind puts in their way!"),
        Entry("1693980", "Dead Space", 44400, 54000, 95400, "Motive Studios", "Electronic Arts", "The sci-fi survival-horror classic Dead Space returns, completely rebuilt from the ground up to offer a deeper, more immersive experience. This remake brings jaw-dropping visual fidelity, suspenseful atmospheric audio, and improvements to gameplay while staying faithful to the original game’s thrilling vision."),
        Entry("1675830", "1000xRESIST", 43200, 50400, 0, "sunset visitor 斜陽過客", "Fellow Traveller", "1000xRESIST is a thrilling sci-fi adventure. The year is unknown, and a disease spread by an alien invasion keeps you underground. You are Watcher. You dutifully fulfil your purpose in serving the ALLMOTHER, until the day you discover a shocking secret that changes everything. The game blends visual novel, walking simulator, and third-person exploration as you navigate nonlinear memories and unrav"),
        Entry("2050650", "Resident Evil 4", 46900, 71154, 155500, "Capcom Development Division 1", "Capcom", "Resident Evil 4 is a remake of the 2005 original Resident Evil 4 reimagined for 2023 to bring state-of-the-art survival horror. Resident Evil 4 preserves the essence of the original game, while introducing modernized gameplay, a reimagined storyline, and vividly detailed graphics to make this the latest survival horror game where life and death, terror and catharsis intersect."),
        Entry("460960", "The Deed: Dynasty", 0, 0, 0, "Pilgrim Adventures", "WhisperGames", "Getting away with murder has never been easy. These three members of a proud and noble family are separated by five centuries, but have in common a vengeful and murderous intent.  Plans must be formed, blood must be spilled and evidence must be planted ..."),
        Entry("1977170", "Jusant", 0, 17550, 36000, "DON'T NOD", "DON'T NOD", "Enjoy meditative vibes in Jusant, an action-puzzle climbing game. Scale an immeasurably tall tower and ascend to new heights alongside your watery companion. Master your climbing tools, find your way up through diverse biomes, and piece together the tower's past."),
        Entry("2442460", "Citizen Sleeper 2: Starward Vector", 0, 0, 0, "Jump Over the Age", "Fellow Traveller", "Citizen Sleeper 2: Starward Vector is a narrative-driven science-fiction RPG in which players take on the role of a Sleeper, an artificial human. Using a tabletop-inspired dice system, players manage resources, make difficult choices, and build relationships while seeking a new life among the settlements of the Starward Belt. Expanding on the original game, the sequel introduces a customizable shi"),
        Entry("1895880", "Ratchet & Clank: Rift Apart", 32400, 51060, 66600, "Insomniac Games", "Sony Interactive Entertainment", "Go dimension-hopping with Ratchet and Clank as they take on an evil emperor from another reality. Jump between action-packed worlds and beyond at mind-blowing speeds, complete with dazzling visuals and an insane arsenal."),
        Entry("2427410", "S.T.A.L.K.E.R.: Shadow of Chornobyl - Enhanced Edition", 0, 0, 0, "GSC Game World", "GSC Game World", "S.T.A.L.K.E.R.: Shadow of Chornobyl, the first chapter of the Legends of the Zone Trilogy, which started it all. Welcome to the former exclusion territory near the Chornobyl Nuclear Power Plant… the most dangerous place on Earth. Play as The Marked One, face sinister mysteries, radiation-soaked anomalous threats and moral dilemmas, as your decisions determine your destiny in this immersive dark sc"),
        Entry("2427420", "S.T.A.L.K.E.R.: Clear Sky - Enhanced Edition", 0, 0, 0, "GSC Game World", "GSC Game World", "S.T.A.L.K.E.R.: Clear Sky is the prequel chapter of the Legends of the Zone Trilogy. With the ability to directly influence the balance of power through Faction Wars, step into the boots of Scar — a seasoned mercenary, able to somehow survive deadly Emissions. Make your way to the Chornobyl Nuclear Power Plant through radiation, anomalies, enemies, mutants, and conflict-raging Zone."),
        Entry("2427430", "S.T.A.L.K.E.R.: Call of Prypiat - Enhanced Edition", 0, 0, 0, "GSC Game World", "GSC Game World", "S.T.A.L.K.E.R.: Call of Prypiat follows the story of special service agent Major Degtyarev as he investigates the fate of a lost expedition. Rich with colorful characters, memorable side stories, and the spirit of true freedom, this chapter delivers a powerful and unforgettable conclusion to the Legends of the Zone Trilogy."),
        Entry("2486740", "Sledders", 0, 0, 0, "Hanki Games", "Bonus Stage Publishing", "Rev' up your sled & dive into fresh powder in Sledders! Realistic, physics-based snowmobile simulator in backcountries full of deep snow. Ride with and against your friends in online multiplayer. Can you reach the peak before others? Show off your sled-skills now on Sledders."),
        Entry("3595230", "Call of Duty®: Modern Warfare® II", 36690, 41240, 58620, "Infinity Ward", "Activision", "Call of Duty: Modern Warfare II drops players into an unprecedented global conflict that features the return of the iconic Operators of Task Force 141."),
        Entry("582660", "Black Desert", 0, 0, 0, "Pearl Abyss", "Pearl Abyss", "Black Desert is a game that tests the limitations of MMORPG by implementing remastered graphics and audio. Enjoy exciting combat and siege, exploration, trading, fishing, training, alchemy, cooking, gathering, hunting, and more in the vast open world."),
        Entry("2881650", "Content Warning", 381600, 77810400, 778420800, "Zorro", "Landfall Games", "Film your friends doing scary things to become SpöökTube famous!"),
        Entry("606150", "Moonlighter", 50400, 61200, 108000, "Digital Sun Games", "Netflix", "Moonlighter is an Action RPG with rogue-lite elements that demonstrates two sides of the coin – revealing everyday routines of Will, an adventurous shopkeeper that secretly dreams of becoming a hero."),
        Entry("997010", "Police Simulator: Patrol Officers", 0, 0, 43200, "Aesir Interactive", "Astragon Entertainment", "Welcome to Brighton! Join the police force of this fictitious American city and experience the day to day life of a Police Officer. Start with citing violations and giving out parking tickets, then work your way towards shouldering more responsibilities. Be part of the community of Brighton, get to know your neighborhood and handle daily police work to fight crime during your shift. Always be toug"),
        Entry("267490", "Batman™: Arkham Origins Blackgate - Deluxe Edition", 28800, 57600, 86400, "Armature Studio", "WB Games", "Batman: Arkham Origins Blackgate - Deluxe Edition amplifies the 2.5-D game developed by Armature Studio with new maps, enemy encounters, difficulty levels, and batsuits, all with enhanced visuals.  A companion game to Batman: Arkham Origins, players can continue the storyline of the console version and discover more details of the Dark Knight’s past."),
        Entry("1578650", "Citizen Sleeper", 0, 20400, 0, "Jump Over the Age", "Fellow Traveller", "Roleplaying in the ruins of interplanetary capitalism. Live the life of an escaped worker, washed-up on a lawless station at the edge of an interstellar society. Inspired by the flexibility and freedom of TTRPGs, explore the station, choose your friends, escape your past and change your future."),
        Entry("362890", "Black Mesa", 34200, 38400, 217350, "Crowbar Collective", "Crowbar Collective", "Black Mesa is a re-envisioning of Valve Software's classic science fiction first person shooter, Half-Life. Powered by Source Engine, You will re-visit the inaugural role of Gordon Freeman and his memorable journey through the Black Mesa Research Facility. Expect detailed environments to explore, a huge cast of characters and experimental weaponry. All-new music, voice acting, choreography and add"),
        Entry("504390", "Along the Edge", 3600, 10800, 18000, "Nova-Box", "Nova-Box", "Along the Edge is a visual novel set in the European countryside, where your choices impact the main character's personality and appearance."),
        Entry("599140", "Graveyard Keeper", 0, 140400, 0, "Lazy Bear Games", "tinyBuild", "Graveyard Keeper is the most inaccurate medieval cemetery management sim of the year. Build & manage your own graveyard while finding shortcuts to cut costs, expand into entertainment with witch-burning festivals, and scare nearby villagers into attending church. This is a game of capitalism and doing whatever it takes to build a thriving business."),
        Entry("383870", "Firewatch", 14412, 16953, 21042, "Campo Santo", "Panic", "Firewatch is a single-player first-person video game where you, as a man named Henry, explore the Wyoming wilderness after taking a summer job as a fire lookout. What is supposed to be a peaceful respite from your complicated life takes a turn when you start to question some of the things that are happening to you.  Your only human connection is over a handheld radio, which you’ll use to speak wit"),
        Entry("553420", "TUNIC", 42000, 62800, 112200, "Andrew Shouldice", "Finji", "Tunic is an action adventure about a tiny fox in a big world. Explore the wilderness, discover spooky ruins, and fight terrible creatures from long ago."),
        Entry("552500", "Warhammer: Vermintide 2", 72000, 106200, 252000, "Fatshark", "Fatshark", "Warhammer: Vermintide 2 is the sequel to the critically acclaimed Vermintide. It's time for players to return to the memorable first-person co-op experience with intense world class melee action."),
        Entry("1533420", "Neon White", 28800, 0, 0, "Ben Esposito", "Annapurna Interactive", "Neon White is a single-player speedrunning FPS where you can sacrifice your guns for godlike parkour moves."),
        Entry("1244090", "Sea of Stars: Sunset Edition", 72000, 117600, 157440, "Sabotage", "Sabotage", "Sea of Stars is a turn-based RPG inspired by the classics. Promising the Sabotage touch in every system, Sea of Stars aims to modernize the classic RPG in terms of turn-based combat, storytelling, exploration and interactions with the environment, while still offering a hearty slice of nostalgia and good old, simple fun."),
        Entry("277590", "Assassin's Creed Freedom Cry", 14400, 22800, 0, "Ubisoft Québec", null, "Born a slave, Adewale found freedom as a pirate aboard Edward Kenway’s ship, the Jackdaw. 15 years later, Adewale has become a trained Assassin who finds himself shipwrecked in Saint-Domingue without weapons or crew. He now has to acquire a ship and gather his own crew to free the slaves and avenge them. Over 3 hours of new single-player gameplay!"),
        Entry("409710", "BioShock Remastered", 43200, 47476, 104400, "2K Australia", "2K Games", "BioShock Remastered was released as a part of BioShock: The Collection and also available separately for PC. The remastered version has achievements, full controller support, high resolution textures, models and interface, and 4K resolution support."),
        Entry("952060", "Resident Evil 3", 12600, 26485, 64800, "Capcom Development Division 1", "Capcom", "Resident Evil 3 is a remake of the original Resident Evil 3: Nemesis released in 1999. It updates the story and gameplay for a modern audience. Like the Resident Evil 2 remake, the game uses over-the-shoulder third person point of view similar to Resident Evil 4 and later installments. Players will spend most of their time playing as Jill Valentine, although on some occasions they will assume the"),
        Entry("261030", "The Walking Dead: Season Two", 30600, 36210, 45500, "Telltale Games", "Skybound Games", "Similar to the previous season, The Walking Dead: Season Two is a point-and-click adventure game. The player, in control of Clementine, can direct the character around the environment, examine and interact with various scenery elements and collect and use objects to advance the story. The player can also initiate conversations with non-player characters via conversation trees. Certain replies from"),
        Entry("1134700", "Wild Terra 2: New Lands", 0, 0, 0, "Juvty Worlds", "Juvty Worlds", "Play your role in the life-filled medieval world controlled by players. Live on an inhabited territory or conquer New Continents in new seasons! MMORPG full of logically interconnected worked out little things that create a unique immersion and the spirit of adventure!"),
        Entry("617480", "Tower of Time", 0, 0, 0, "Event Horizon", "Event Horizon", "RPG with 3d graphics, real time combat and deep and mature story with real time combat with time manipulation, tactical and challenging battles, seven diverse classes to choose for 4-man party, and more."),
        Entry("261570", "Ori and the Blind Forest", 25200, 31650, 44322, "Moon Studios", "Microsoft Studios", "The forest of Nibel is dying. After a powerful storm sets a series of devastating events in motion, an unlikely hero must journey to find his courage and confront a dark nemesis to save his home. Ori and the Blind Forest tells the tale of a young orphan destined for heroics, through a visually stunning action-platformer crafted by Moon Studios for Xbox One and PC. Featuring hand-painted artwork, m"),
        Entry("409720", "BioShock 2 Remastered", 42000, 51744, 126900, "2K Australia", "2K Games", "BioShock 2 Remastered was released as a part of BioShock: The Collection and also available separately for PC. The remastered version has achievements, full controller support, high resolution textures, models and interface, and 4K resolution support."),
        Entry("1588550", "Cairn", 37800, 54900, 73800, "The Game Bakers", "The Game Bakers", "Reach a summit never climbed before in this survival-climber from the creators of Furi and Haven. Climb anywhere and plan your route carefully, managing pitons and resources to survive the unforgiving Mount Kami. Discover what Aava is willing to sacrifice to achieve the ascent of a lifetime."),
        Entry("1604030", "V Rising", 0, 0, 0, "Stunlock Studios", "Stunlock Studios", "Awaken as a vampire. Hunt for blood in nearby settlements to regain your strength and evade the scorching sun to survive. Raise your castle and thrive in an ever-changing open world full of mystery. Gain allies online and conquer the land of the living."),
        Entry("1053710", "The Red Lantern", 0, 0, 0, "Timberline Studio Inc.", "Timberline Studio Inc.", "The Red Lantern is a narrative, survival game where you and your team of 5 sled dogs, lost in the wilderness, must navigate the ever-changing events of the Alaskan bush to find your way home.  Choose how you want to interact with the world, do you tackle it head on hunting everything that moves, or do you take a more cautious approach?"),
        Entry("1180660", "Tell Me Why", 0, 37500, 43200, "DON'T NOD", "Xbox Game Studios", "Tell Me Why is the latest narrative adventure game from DONTNOD Entertainment, the studio behind the beloved franchise, Life is Strange. In this intimate mystery, twins Tyler and Alyson Ronan use their supernatural bond to unravel the mysteries of their loving but troubled childhood in beautiful small-town Alaska."),
        Entry("894020", "Death's Door", 32400, 42672, 57600, "Acid Nerve", "Devolver Digital", "Death's Door is an action-adventure game developed by Acid Nerve and published by Devolver Digital. Released in 2021, it follows a crow reaper tasked with collecting souls in a mysterious, atmospheric world. The game features exploration, fast-paced combat, and puzzle-solving."),
        Entry("1620730", "Hell is Us", 66600, 92400, 117000, "Rogue Factor", "Nacon", "If war is the closest we get to hell on earth, it's because Earth harbours the worst of demons: humankind. In an isolated country ravaged by infighting, discover the secrets of your past and deal with the repercussions of a mysterious calamity."),
    )
}